<?php
session_start();
if(empty($_SESSION['user_id']) || empty($_SESSION['company_id'])) { header('Location: login.php'); exit; }
require_once __DIR__.'/db.php';
require_once __DIR__.'/credit_note_lib.php';
ensurePurchaseVatAdjustmentSchema($pdo);
function h(string $value):string { return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$companyId=(int)$_SESSION['company_id']; $id=(int)($_GET['invoice_id']??0);
$stmt=$pdo->prepare('SELECT supplier_invoice_number,invoice_date FROM purchase_invoices WHERE company_id=? AND id=?'); $stmt->execute([$companyId,$id]); $invoice=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$invoice) { http_response_code(404); exit('Ostuarvet ei leitud.'); }
$stmt=$pdo->prepare('SELECT * FROM purchase_vat_adjustment_history WHERE company_id=? AND invoice_id=? ORDER BY id DESC'); $stmt->execute([$companyId,$id]); $history=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare('SELECT id,CONCAT(code,\' — \',name) FROM accounts WHERE company_id=?'); $stmt->execute([$companyId]); $accounts=$stmt->fetchAll(PDO::FETCH_KEY_PAIR);
?>
<!doctype html><html lang="et"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Käibemaksu paranduste ajalugu</title><style>body{font:16px Arial;background:#f4f7fb;color:#263746;max-width:1000px;margin:30px auto;padding:0 18px}.card{background:white;border:1px solid #dce3ec;border-radius:12px;padding:22px;margin:16px 0}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px;border-bottom:1px solid #e5eaf0}.small{font-size:14px;color:#526579;line-height:1.5}a{color:#1769aa}</style></head><body><section class="card"><h1>Käibemaksu paranduste ajalugu</h1><p>Ostuarve <strong><?= h($invoice['supplier_invoice_number']) ?></strong>, <?= h($invoice['invoice_date']) ?>.</p><p class="small">Mahaarvamata käibemaks suurendab algse arve kulu või vara maksumust ning vähendab sisendkäibemaksu kontot. Pöördmaksu käibemaksukohustust see ei vähenda. Muudatused kirjendatakse eraldi paranduskannetena; algne arve ja tarnijavõlg säilivad.</p><p><a href="purchase_invoices.php?id=<?= $id ?>">Tagasi ostuarvele</a> · <a href="kmd_inf_preview.php?year=<?= h(substr($invoice['invoice_date'],0,4)) ?>&amp;month=<?= (int)substr($invoice['invoice_date'],5,2) ?>">KMD INF eelvaade</a></p></section>
<?php if(!$history): ?><section class="card">Selle arve automaatse paranduse ajalugu veel puudub. Salvesta arve mahaarvatav summa KMD INF eelvaates.</section><?php endif; ?>
<?php foreach($history as $event): ?><?php $before=json_decode($event['before_json'],true,512,JSON_THROW_ON_ERROR); $after=json_decode($event['after_json'],true,512,JSON_THROW_ON_ERROR); ?><section class="card"><h2><?= h($event['entry_date']) ?> — <?= $event['event_name']==='cancellation'?'Paranduse tühistamine':($event['event_name']==='credit'?'Kreeditarve parandus':'Mahaarvamise kinnitus või muudatus') ?></h2><p>Mahaarvatav KM: <?= h($before['deductible_cents']===null?'kinnitamata':creditDecimal((int)$before['deductible_cents']).' €') ?> → <?= h(creditDecimal((int)$after['deductible_cents'])) ?> €.</p><p>Mahaarvamata KM: <?= h(creditDecimal((int)$before['amount_cents'])) ?> € → <?= h(creditDecimal((int)$after['amount_cents'])) ?> €.</p><p><?php if($event['journal_entry_id']): ?><a href="entry.php?id=<?= (int)$event['journal_entry_id'] ?>">Vaata paranduskannet nr <?= (int)$event['journal_entry_id'] ?></a><?php else: ?>Rahalist muutust ei olnud; uut pearaamatukannet ei loodud.<?php endif; ?></p><table><thead><tr><th>Kulu-/varakonto</th><th>Mahaarvamata KM pärast muudatust</th></tr></thead><tbody><?php $totals=[]; foreach($after['allocations'] as $allocation) $totals[$allocation['account_id']]=($totals[$allocation['account_id']]??0)+(int)$allocation['amount']; foreach($totals as $account=>$amount): ?><tr><td><?= h($accounts[$account]??('Konto '.$account)) ?></td><td><?= h(creditDecimal($amount)) ?> €</td></tr><?php endforeach; ?></tbody></table><p class="small">Salvestatud <?= h($event['created_at']) ?> · kasutaja nr <?= (int)$event['created_by'] ?></p></section><?php endforeach; ?></body></html>
